      sendHeaders: true, headerParameters: { parameters: [{ name: 'Version', value: '2021-07-28' }] },
      sendBody: true, specifyBody: 'json',
      jsonBody: expr('{{ JSON.stringify({ locationId: "va82O7V3l50t4My9T2zQ", properties: $json.properties }) }}'),
